    def demand_of(node, demands):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return demands.get(node, 1)
        try:
            return demands[node]
        except Exception:
            return 1

    def coord_of(node, coords):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(node, None)
        try:
            return coords[node]
        except Exception:
            return None

    def dist(a, b, coords):
        pa = coord_of(a, coords)
        pb = coord_of(b, coords)
        if pa is None or pb is None:
            return 0
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        return (dx * dx + dy * dy) ** 0.5

    depot = get_depot(instance)
    capacity = get_capacity(instance)
    coords = get_coords(instance)
    demands = get_demands(instance)
    customers = all_customer_ids(instance, depot)

    if capacity is None:
        total = 0
        for c in customers:
            total += demand_of(c, demands)
        capacity = max(1, total)

    unserved = set(customers)

    def route_load(route):
        s = 0
        for n in route:
            s += demand_of(n, demands)
        return s

    def route_cost(route):
        if not route:
            return 0
        c = dist(depot, route[0], coords)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1], coords)
        c += dist(route[-1], depot, coords)
        return c

    routes = []

    # Greedy seed routes: nearest feasible insertion from depot.
    while unserved:
        best_start = None
        best_key = None
        for c in unserved:
            d = demand_of(c, demands)
            if d <= capacity:
                key = (dist(depot, c, coords), d, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best_start = c
        if best_start is None:
            best_start = min(unserved, key=lambda c: (demand_of(c, demands), dist(depot, c, coords), c))
        route = [best_start]
        unserved.remove(best_start)
        load = demand_of(best_start, demands)
        current = best_start
        while True:
            best = None
            best_key = None
            for c in unserved:
                d = demand_of(c, demands)
                if load + d > capacity:
                    continue
                key = (dist(current, c, coords), dist(depot, c, coords), d, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = c
            if best is None:
                break
            route.append(best)
            unserved.remove(best)
            load += demand_of(best, demands)
            current = best
        routes.append(route)

    # Repair: if any route is over capacity, split it deterministically.
    repaired = []
    for r in routes:
        cur = []
        load = 0
        for n in r:
            d = demand_of(n, demands)
            if cur and load + d > capacity:
                repaired.append(cur)
                cur = [n]
                load = d
            else:
                cur.append(n)
                load += d
        if cur:
            repaired.append(cur)
    routes = repaired

    # Inter-route relocation improvement.
    improved = True
    while improved:
        improved = False
        best_move = None
        best_gain = 0
        for i in range(len(routes)):
            ri = routes[i]
            for p, node in enumerate(ri):
                dnode = demand_of(node, demands)
                prev_i = depot if p == 0 else ri[p - 1]
                next_i = depot if p == len(ri) - 1 else ri[p + 1]
                remove_saving = dist(prev_i, node, coords) + dist(node, next_i, coords) - dist(prev_i, next_i, coords)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dnode > capacity:
                        continue
                    for pos in range(len(rj) + 1):
                        prev_j = depot if pos == 0 else rj[pos - 1]
                        next_j = depot if pos == len(rj) else rj[pos]
                        add_cost = dist(prev_j, node, coords) + dist(node, next_j, coords) - dist(prev_j, next_j, coords)
                        gain = remove_saving - add_cost
                        if gain > best_gain + 1e-12 or (abs(gain - best_gain) <= 1e-12 and best_move is not None and (i, p, j, pos, node) < best_move[0]):
                            best_gain = gain
                            best_move = ((i, p, j, pos, node), gain)
        if best_move is not None and best_gain > 1e-12:
            (i, p, j, pos, node), _ = best_move
            node = routes[i][p]
            routes[i].pop(p)
            routes[j].insert(pos, node)
            if not routes[i]:
                routes.pop(i)
            improved = True

    # Intra-route 2-opt for routes with coordinates.
    if coords is not None:
        changed = True
        while changed:
            changed = False
            for r_idx in range(len(routes)):
                r = routes[r_idx]
                n = len(r)
                if n < 4:
                    continue
                best_delta = 0
                best_pair = None
                for i in range(n - 2):
                    a = depot if i == 0 else r[i - 1]
                    b = r[i]
                    for k in range(i + 2, n):
                        c = r[k]
                        d = depot if k == n - 1 else r[k + 1]
                        delta = (dist(a, c, coords) + dist(b, d, coords)) - (dist(a, b, coords) + dist(c, d, coords))
                        if delta < best_delta - 1e-12:
                            best_delta = delta
                            best_pair = (i, k)
                if best_pair is not None:
                    i, k = best_pair
                    routes[r_idx] = r[:i] + r[i:k + 1][::-1] + r[k + 1:]
                    changed = True

    # Final deterministic cleanup: remove empties and ensure all customers exactly once.
    final = []
    seen = set()
    for r in routes:
        rr = []
        load = 0
        for n in r:
            if n in seen:
                continue
            d = demand_of(n, demands)
            if rr and load + d > capacity:
                final.append(rr)
                rr = [n]
                load = d
            else:
                rr.append(n)
                load += d
            seen.add(n)
        if rr:
            final.append(rr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        d = demand_of(c, demands)
        best_idx = None
        best_pos = None
        best_cost = None
        for i in range(len(final)):
            if route_load(final[i]) + d > capacity:
                continue
            r = final[i]
            for pos in range(len(r) + 1):
                prev_n = depot if pos == 0 else r[pos - 1]
                next_n = depot if pos == len(r) else r[pos]
                cost = dist(prev_n, c, coords) + dist(c, next_n, coords) - dist(prev_n, next_n, coords)
                key = (cost, i, pos)
                if best_cost is None or key < best_cost:
                    best_cost = key
                    best_idx = i
                    best_pos = pos
        if best_idx is None:
            final.append([c])
        else:
            final[best_idx].insert(best_pos, c)

    # Remove any accidental empties.
    return [r for r in final if r]
